function New-CustomAppProductionRecoveryAwarePermitAtomicDeniedV010 {
    param([Parameter(Mandatory=$true)][string]$Reason,[bool]$MutationInvoked=$false,[bool]$RollbackAttempted=$false,[bool]$RollbackOk=$false,[AllowNull()]$RollbackResult=$null)
    return [pscustomobject]@{
        ok=$false;reason=$Reason;result=$null;mutation_invoked=$MutationInvoked;rollback_attempted=$RollbackAttempted;rollback_ok=$RollbackOk;rollback_result=$RollbackResult
        recovery_revalidated_immediately_before_atomic=$false;live_code_swap_performed=$false;session_key_accepted=$false;session_key_persisted=$false;session_key_exposed=$false
        result_is_authority=$false;requires_exact_rollback_on_failure=$true;requires_transaction_finalization=$false;requires_spicetify_apply_phase=$true;requires_fresh_post_swap_apply_admission=$true
        apply_execution_authorized=$false;spicetify_apply_authorized=$false;additional_mutation_authorized=$false;live_destination_authorized=$false;production_execution_authorized=$false;production_mutation_authorized=$false
    }
}

function Remove-CustomAppProductionRecoveryAwarePermitAtomicTransactionV010 {
    param([AllowNull()][string]$TransactionRoot,[Parameter(Mandatory=$true)][string]$LivePath)
    if([string]::IsNullOrWhiteSpace($TransactionRoot) -or -not (Test-Path -LiteralPath $TransactionRoot)){return [pscustomobject]@{ok=$true;reason='transaction-workspace-absent'}}
    try{
        $live=[IO.Path]::GetFullPath($LivePath).TrimEnd([IO.Path]::DirectorySeparatorChar,[IO.Path]::AltDirectorySeparatorChar)
        $parent=[IO.Path]::GetDirectoryName($live)
        $txn=[IO.Path]::GetFullPath($TransactionRoot).TrimEnd([IO.Path]::DirectorySeparatorChar,[IO.Path]::AltDirectorySeparatorChar)
        if(-not ([IO.Path]::GetDirectoryName($txn)).Equals($parent,[StringComparison]::OrdinalIgnoreCase)){return [pscustomobject]@{ok=$false;reason='transaction-workspace-parent-mismatch'}}
        $leaf=[IO.Path]::GetFileName($txn)
        if($leaf -notmatch '^\.spotify-control-txn-[0-9a-fA-F]{32}$'){return [pscustomobject]@{ok=$false;reason='transaction-workspace-name-invalid'}}
        Remove-CustomAppAtomicDirectoryV010 -Path $txn -ExpectedParent $parent -ExpectedName $leaf
        if(Test-Path -LiteralPath $txn){return [pscustomobject]@{ok=$false;reason='transaction-workspace-remained'}}
        return [pscustomobject]@{ok=$true;reason='transaction-workspace-cleaned'}
    }catch{return [pscustomobject]@{ok=$false;reason=('transaction-workspace-cleanup-failed:'+[string]$_.Exception.Message)}}
}

function Restore-CustomAppProductionRecoveryAwarePermitAtomicAfterWrapperFailureV010 {
    param([Parameter(Mandatory=$true)][string]$LivePath,[Parameter(Mandatory=$true)]$PreparedResult,[AllowNull()][string]$TransactionRoot,[Parameter(Mandatory=$true)][string]$LocalAppDataRoot,[Parameter(Mandatory=$true)][string]$AppDataRoot)
    $restore=$null
    try{
        $restore=Restore-CustomAppProductionAtomicLiveSwapV010 -LivePath $LivePath -AppBackupPath ([string]$PreparedResult.app_backup_path) -ExpectedAppBackupTreeSha256 ([string]$PreparedResult.app_backup_tree_sha256) -PersistenceBackupPath ([string]$PreparedResult.persistence_backup_path) -ExpectedPersistenceFingerprint ([string]$PreparedResult.persistence_fingerprint) -LocalAppDataRoot $LocalAppDataRoot -AppDataRoot $AppDataRoot
    }catch{$restore=[pscustomobject]@{ok=$false;reason=('wrapper-restore-threw:'+[string]$_.Exception.Message)}}
    $cleanup=Remove-CustomAppProductionRecoveryAwarePermitAtomicTransactionV010 -TransactionRoot $TransactionRoot -LivePath $LivePath
    return [pscustomobject]@{ok=([bool]$restore.ok -and [bool]$cleanup.ok);reason=$(if([bool]$restore.ok -and [bool]$cleanup.ok){'wrapper-app-persistence-restored-and-transaction-cleaned'}else{('wrapper-rollback-incomplete:restore='+[string]$restore.reason+';cleanup='+[string]$cleanup.reason)});restore=$restore;cleanup=$cleanup}
}

