        [string]$Result.recovery_revalidated_immediately_before_atomic,[string]$Result.byte_real_live_reverified,[string]$Result.historical_consumption_reverified_after_atomic,[string]$Result.same_app_newer_consumption_absent,[string]$Result.live_code_swap_performed,
        [string]$Result.rollback_attempted,[string]$Result.rollback_ok,[string]$Result.session_key_accepted,[string]$Result.session_key_persisted,[string]$Result.session_key_exposed,[string]$Result.result_is_authority,
        [string]$Result.requires_transaction_finalization,[string]$Result.requires_spicetify_apply_phase,[string]$Result.requires_fresh_post_swap_apply_admission,[string]$Result.requires_exact_rollback_on_failure,
        [string]$Result.apply_execution_authorized,[string]$Result.spicetify_apply_authorized,[string]$Result.additional_mutation_authorized,[string]$Result.live_destination_authorized,[string]$Result.production_execution_authorized,[string]$Result.production_mutation_authorized
    ) -join "`n"
}

function Test-CustomAppProductionRecoveryAwarePermitAtomicLiveSwapResultV010 {
    param([AllowNull()]$Result)
    if($null -eq $Result){return [pscustomobject]@{ok=$false;reason='recovery-aware-atomic-result-null'}}
    foreach($f in @('schema','managed_by','qualified_recovery_aware_pre_apply_head','qualified_recovery_aware_pre_apply_core_blob','qualified_atomic_mutation_head','qualified_atomic_mutation_core_blob','qualified_generic_atomic_head','qualified_generic_atomic_core_blob','status','name','source_identity','transaction_id','github_repo_id','surface_kind','remote_commit_sha','consumption_id','consumption_persistence_fingerprint','historical_consumption_envelope_sha256','current_consumption_envelope_sha256','current_consumption_revision','recovery_pre_mutation_admission_fingerprint','recovery_pre_apply_result_fingerprint','recovery_stage_result_fingerprint','mutation_result_fingerprint','mutation_caller_admission_fingerprint','actual_pre_live_runtime_tree_sha256','actual_pre_live_full_tree_sha256','old_live_tree_sha256','post_runtime_tree_sha256','binding_fingerprint','live_path','transaction_root','old_live_path','persistence_fingerprint','swapped_at','recovery_revalidated_immediately_before_atomic','byte_real_live_reverified','historical_consumption_reverified_after_atomic','same_app_newer_consumption_absent','live_code_swap_performed','rollback_attempted','rollback_ok','session_key_accepted','session_key_persisted','session_key_exposed','result_is_authority','requires_transaction_finalization','requires_spicetify_apply_phase','requires_fresh_post_swap_apply_admission','requires_exact_rollback_on_failure','apply_execution_authorized','spicetify_apply_authorized','additional_mutation_authorized','live_destination_authorized','production_execution_authorized','production_mutation_authorized','result_fingerprint')){if(-not $Result.PSObject.Properties[$f]){return [pscustomobject]@{ok=$false;reason=('recovery-aware-atomic-result-field-missing-'+$f)}}}
    if([int]$Result.schema -ne $CustomAppProductionRecoveryAwarePermitAtomicLiveSwapSchema -or [string]$Result.managed_by -cne $CustomAppProductionRecoveryAwarePermitAtomicLiveSwapManagedBy -or [string]$Result.status -cne 'recovery-aware-atomic-live-code-swap-verified-no-spicetify-apply'){return [pscustomobject]@{ok=$false;reason='recovery-aware-atomic-result-owner-schema-status-mismatch'}}
    if([string]$Result.qualified_recovery_aware_pre_apply_head -cne $CustomAppProductionRecoveryAwarePermitAtomicLiveSwapQualifiedPreApplyHead -or [string]$Result.qualified_recovery_aware_pre_apply_core_blob -cne $CustomAppProductionRecoveryAwarePermitAtomicLiveSwapQualifiedPreApplyCoreBlob -or [string]$Result.qualified_atomic_mutation_head -cne $CustomAppProductionRecoveryAwarePermitAtomicLiveSwapQualifiedMutationHead -or [string]$Result.qualified_atomic_mutation_core_blob -cne $CustomAppProductionRecoveryAwarePermitAtomicLiveSwapQualifiedMutationCoreBlob -or [string]$Result.qualified_generic_atomic_head -cne $CustomAppProductionRecoveryAwarePermitAtomicLiveSwapQualifiedGenericAtomicHead -or [string]$Result.qualified_generic_atomic_core_blob -cne $CustomAppProductionRecoveryAwarePermitAtomicLiveSwapQualifiedGenericAtomicCoreBlob){return [pscustomobject]@{ok=$false;reason='recovery-aware-atomic-result-lineage-mismatch'}}
    foreach($f in @('transaction_id','consumption_id','consumption_persistence_fingerprint','historical_consumption_envelope_sha256','current_consumption_envelope_sha256','recovery_pre_mutation_admission_fingerprint','recovery_pre_apply_result_fingerprint','recovery_stage_result_fingerprint','mutation_result_fingerprint','mutation_caller_admission_fingerprint','actual_pre_live_runtime_tree_sha256','actual_pre_live_full_tree_sha256','old_live_tree_sha256','post_runtime_tree_sha256','binding_fingerprint','persistence_fingerprint','result_fingerprint')){if(-not (Test-CustomAppProductionRecoveryAwarePermitAtomicSha256V010 (([string]$Result.$f).Trim().ToLowerInvariant()))){return [pscustomobject]@{ok=$false;reason=('recovery-aware-atomic-result-invalid-'+$f)}}}
    if($Result.PSObject.Properties['preserved_git_tree_sha256'] -and -not [string]::IsNullOrWhiteSpace([string]$Result.preserved_git_tree_sha256) -and -not (Test-CustomAppProductionRecoveryAwarePermitAtomicSha256V010 (([string]$Result.preserved_git_tree_sha256).Trim().ToLowerInvariant()))){return [pscustomobject]@{ok=$false;reason='recovery-aware-atomic-result-invalid-preserved-git-tree'}}
    if(([string]$Result.remote_commit_sha).Trim().ToLowerInvariant() -notmatch '^[0-9a-f]{40}$'){return [pscustomobject]@{ok=$false;reason='recovery-aware-atomic-result-remote-commit-invalid'}}
    try{if([int64]$Result.github_repo_id -le 0 -or [int64]$Result.current_consumption_revision -lt 1){return [pscustomobject]@{ok=$false;reason='recovery-aware-atomic-result-numeric-field-invalid'}}}catch{return [pscustomobject]@{ok=$false;reason='recovery-aware-atomic-result-numeric-field-invalid'}}
    foreach($f in @('recovery_revalidated_immediately_before_atomic','byte_real_live_reverified','historical_consumption_reverified_after_atomic','same_app_newer_consumption_absent','live_code_swap_performed','session_key_accepted','requires_transaction_finalization','requires_spicetify_apply_phase','requires_fresh_post_swap_apply_admission','requires_exact_rollback_on_failure')){if(-not [bool]$Result.$f){return [pscustomobject]@{ok=$false;reason=('recovery-aware-atomic-result-required-flag-false-'+$f)}}}
    foreach($f in @('rollback_attempted','rollback_ok','session_key_persisted','session_key_exposed','result_is_authority','apply_execution_authorized','spicetify_apply_authorized','additional_mutation_authorized','live_destination_authorized','production_execution_authorized','production_mutation_authorized')){if([bool]$Result.$f){return [pscustomobject]@{ok=$false;reason=('recovery-aware-atomic-result-authority-or-failure-flag-true-'+$f)}}}
    $at=[DateTimeOffset]::MinValue;if(-not [DateTimeOffset]::TryParse([string]$Result.swapped_at,[ref]$at)){return [pscustomobject]@{ok=$false;reason='recovery-aware-atomic-result-time-invalid'}}
    foreach($f in @('live_path','transaction_root','old_live_path','name','source_identity','surface_kind')){if([string]::IsNullOrWhiteSpace([string]$Result.$f)){return [pscustomobject]@{ok=$false;reason=('recovery-aware-atomic-result-empty-'+$f)}}}
    $expected=Get-CustomAppProductionRecoveryAwarePermitAtomicSha256V010 (Get-CustomAppProductionRecoveryAwarePermitAtomicResultMaterialV010 -Result $Result)
    if(([string]$Result.result_fingerprint).Trim().ToLowerInvariant() -cne $expected){return [pscustomobject]@{ok=$false;reason='recovery-aware-atomic-result-fingerprint-mismatch'}}
    return [pscustomobject]@{ok=$true;reason='recovery-aware-atomic-result-valid-zero-apply-authority';result_fingerprint=$expected;production_mutation_authorized=$false}
}

function Invoke-CustomAppProductionRecoveryAwarePermitAtomicLiveSwapV010 {
    param(
        [Parameter(Mandatory=$true)]$RecoveryAwareStageExecutorResult,[Parameter(Mandatory=$true)]$RecoveryAwarePreparedResult,
        [Parameter(Mandatory=$true)][string]$Name,[AllowNull()]$LifecycleRow,[AllowNull()]$ProvenanceRow,[AllowNull()]$BindingRow,[AllowNull()]$LifecycleStageResult,[AllowNull()]$ShadowResult,[AllowNull()]$RetirementResumeResult,
        [AllowNull()]$ShadowProtocolQualification,[AllowNull()]$LiveAttestedQualification,
        [Parameter(Mandatory=$true)][string]$AllowedRoot,[Parameter(Mandatory=$true)][string]$RecoveryStoreDirectory,[Parameter(Mandatory=$true)][string]$ConsumptionStoreDirectory,
        [Parameter(Mandatory=$true)][string]$ExpectedTransactionId,[Parameter(Mandatory=$true)][string]$LocalAppDataRoot,[Parameter(Mandatory=$true)][string]$AppDataRoot,
        [Parameter(Mandatory=$true)]$ConsumptionPersistenceResult,[AllowNull()]$Permit,[Parameter(Mandatory=$true)][byte[]]$SessionKey,
        [DateTimeOffset]$Now=[DateTimeOffset]::UtcNow,[int]$MaxRemoteObservationAgeHours=36
    )
    $deny={param([string]$Reason,[bool]$MutationInvoked=$false,[bool]$RollbackAttempted=$false,[bool]$RollbackOk=$false,$RollbackResult=$null) New-CustomAppProductionRecoveryAwarePermitAtomicDeniedV010 -Reason $Reason -MutationInvoked $MutationInvoked -RollbackAttempted $RollbackAttempted -RollbackOk $RollbackOk -RollbackResult $RollbackResult}
    if($SessionKey.Length -lt 32){return & $deny 'recovery-aware-atomic-session-key-too-short'}
    $stageCheck=Test-CustomAppProductionRecoveryAwarePermitStageExecutorResultV010 -Result $RecoveryAwareStageExecutorResult
    if(-not [bool]$stageCheck.ok){return & $deny ('recovery-aware-atomic-stage-result-invalid:'+[string]$stageCheck.reason)}
    $preparedCheck=Test-CustomAppProductionRecoveryAwarePermitPreApplyPreparedResultV010 -Result $RecoveryAwarePreparedResult
    if(-not [bool]$preparedCheck.ok){return & $deny ('recovery-aware-atomic-prepared-result-invalid:'+[string]$preparedCheck.reason)}
    if(([string]$RecoveryAwareStageExecutorResult.name).Trim().ToLowerInvariant() -cne $Name.Trim().ToLowerInvariant() -or ([string]$RecoveryAwarePreparedResult.name).Trim().ToLowerInvariant() -cne $Name.Trim().ToLowerInvariant()){return & $deny 'recovery-aware-atomic-name-mismatch'}
    $tx=$ExpectedTransactionId.Trim().ToLowerInvariant();if(-not (Test-CustomAppProductionRecoveryAwarePermitAtomicSha256V010 $tx)){return & $deny 'recovery-aware-atomic-transaction-id-invalid'}
    if(([string]$RecoveryAwareStageExecutorResult.transaction_id).Trim().ToLowerInvariant() -cne $tx -or ([string]$RecoveryAwarePreparedResult.transaction_id).Trim().ToLowerInvariant() -cne $tx){return & $deny 'recovery-aware-atomic-transaction-id-mismatch'}
    if(([string]$RecoveryAwarePreparedResult.recovery_stage_result_fingerprint).Trim().ToLowerInvariant() -cne ([string]$RecoveryAwareStageExecutorResult.result_fingerprint).Trim().ToLowerInvariant()){return & $deny 'recovery-aware-atomic-stage-prepared-fingerprint-mismatch'}
    foreach($f in @('source_identity','github_repo_id','surface_kind','remote_commit_sha','consumption_id','consumption_persistence_fingerprint','historical_consumption_envelope_sha256','binding_fingerprint')){if(([string]$RecoveryAwarePreparedResult.$f).Trim().ToLowerInvariant() -cne ([string]$RecoveryAwareStageExecutorResult.$f).Trim().ToLowerInvariant()){return & $deny ('recovery-aware-atomic-stage-prepared-continuity-drift-'+$f)}}

    $binding=Test-CustomAppStageBindingRowV010 -BindingRow $BindingRow -ExpectedName $Name
    if(-not [bool]$binding.ok){return & $deny ('recovery-aware-atomic-binding-denied:'+[string]$binding.reason)}
    foreach($pair in @(@('source_identity','source'),@('surface_kind','surface'),@('remote_commit_sha','commit_sha'),@('remote_tree_sha256','remote_tree_sha256'),@('binding_fingerprint','binding_fingerprint'))){if(([string]$RecoveryAwareStageExecutorResult.($pair[0])).Trim().ToLowerInvariant() -cne ([string]$binding.($pair[1])).Trim().ToLowerInvariant()){return & $deny ('recovery-aware-atomic-stage-binding-mismatch-'+$pair[0])}}
    try{if([int64]$RecoveryAwareStageExecutorResult.github_repo_id -ne [int64]$binding.repo_id){return & $deny 'recovery-aware-atomic-stage-binding-mismatch-github_repo_id'}}catch{return & $deny 'recovery-aware-atomic-stage-repo-id-invalid'}

    $freshLive=Test-CustomAppProductionStageExecutorLiveBaselineV010 -LifecycleRow $LifecycleRow -Permit $Permit -BindingRow $BindingRow -Name $Name
    if(-not [bool]$freshLive.ok){return & $deny ('recovery-aware-atomic-live-revalidation-denied:'+[string]$freshLive.reason)}
    if(([string]$freshLive.tree_sha256).Trim().ToLowerInvariant() -cne ([string]$RecoveryAwareStageExecutorResult.local_tree_sha256).Trim().ToLowerInvariant()){return & $deny 'recovery-aware-atomic-live-stage-local-tree-continuity-mismatch'}
    try{
        if($null -eq $LifecycleRow -or @($LifecycleRow.locations).Count -ne 1){return & $deny 'recovery-aware-atomic-live-path-not-single'}
        $livePath=[IO.Path]::GetFullPath([string]$LifecycleRow.locations[0]).TrimEnd([IO.Path]::DirectorySeparatorChar,[IO.Path]::AltDirectorySeparatorChar)
        $actualRuntime=Get-CustomAppLocalRuntimeBaseline -Name $Name -AppPath $livePath
        if(-not [bool]$actualRuntime.safe -or -not [bool]$actualRuntime.installable -or (Test-CustomAppLocalRuntimeBaselineMutationAuthority $actualRuntime)){return & $deny 'recovery-aware-atomic-byte-real-runtime-unsafe'}
        $actualFull=Get-CustomAppUpdateTreeSnapshotV010 -Root $livePath
    }catch{return & $deny ('recovery-aware-atomic-byte-real-live-read-failed:'+[string]$_.Exception.Message)}
    if(([string]$actualFull.tree_sha256).Trim().ToLowerInvariant() -cne ([string]$RecoveryAwarePreparedResult.app_backup_tree_sha256).Trim().ToLowerInvariant() -or [int]$actualFull.file_count -ne [int]$RecoveryAwarePreparedResult.app_backup_file_count -or [int64]$actualFull.total_bytes -ne [int64]$RecoveryAwarePreparedResult.app_backup_total_bytes){return & $deny 'recovery-aware-atomic-byte-real-live-backup-mismatch'}

    $recovery=Resolve-CustomAppProductionRecoveryAwarePermitStageAcquisitionAdmissionV010 -Name $Name -LifecycleRow $LifecycleRow -ProvenanceRow $ProvenanceRow -BindingRow $BindingRow -StageResult $LifecycleStageResult -ShadowResult $ShadowResult -RetirementResumeResult $RetirementResumeResult -CurrentBaseline $freshLive.baseline -ShadowProtocolQualification $ShadowProtocolQualification -LiveAttestedQualification $LiveAttestedQualification -AllowedRoot $AllowedRoot -RecoveryStoreDirectory $RecoveryStoreDirectory -ConsumptionStoreDirectory $ConsumptionStoreDirectory -ExpectedTransactionId $ExpectedTransactionId -LocalAppDataRoot $LocalAppDataRoot -AppDataRoot $AppDataRoot -ConsumptionPersistenceResult $ConsumptionPersistenceResult -Permit $Permit -SessionKey $SessionKey -Now $Now -MaxRemoteObservationAgeHours $MaxRemoteObservationAgeHours
    if($null -eq $recovery -or -not [bool]$recovery.ok -or -not [bool]$recovery.stage_acquisition_eligible -or $null -eq $recovery.receipt){return & $deny ('recovery-aware-atomic-pre-mutation-admission-denied:'+[string]$recovery.reason)}
    $recoveryCheck=Test-CustomAppProductionRecoveryAwarePermitStageAdmissionReceiptV010 -Receipt $recovery.receipt -Now $Now
    if(-not [bool]$recoveryCheck.ok){return & $deny ('recovery-aware-atomic-pre-mutation-admission-invalid:'+[string]$recoveryCheck.reason)}
    foreach($f in @('name','source_identity','transaction_id','github_repo_id','surface_kind','consumption_id','consumption_persistence_fingerprint','historical_consumption_envelope_sha256','binding_fingerprint')){if(([string]$RecoveryAwareStageExecutorResult.$f).Trim().ToLowerInvariant() -cne ([string]$recovery.receipt.$f).Trim().ToLowerInvariant()){return & $deny ('recovery-aware-atomic-pre-mutation-admission-continuity-drift-'+$f)}}

    $mutation=$null
    try{
        $mutation=Invoke-CustomAppProductionAtomicLiveSwapMutationV010 -Name $Name -CallerAdmissionManagedBy ([string]$recovery.receipt.managed_by) -CallerAdmissionFingerprint ([string]$recovery.receipt.admission_fingerprint) -LivePath $livePath -StagePath ([string]$RecoveryAwareStageExecutorResult.stage_path) -ExpectedLiveRuntimeTreeSha256 ([string]$actualRuntime.tree_sha256) -ExpectedLiveFullTreeSha256 ([string]$actualFull.tree_sha256) -ExpectedLiveFullFileCount ([int]$actualFull.file_count) -ExpectedLiveFullTotalBytes ([int64]$actualFull.total_bytes) -ExpectedStageRuntimeTreeSha256 ([string]$RecoveryAwareStageExecutorResult.remote_tree_sha256) -AppBackupPath ([string]$RecoveryAwarePreparedResult.app_backup_path) -ExpectedAppBackupTreeSha256 ([string]$RecoveryAwarePreparedResult.app_backup_tree_sha256) -ExpectedAppBackupFileCount ([int]$RecoveryAwarePreparedResult.app_backup_file_count) -ExpectedAppBackupTotalBytes ([int64]$RecoveryAwarePreparedResult.app_backup_total_bytes) -PersistenceBackupPath ([string]$RecoveryAwarePreparedResult.persistence_backup_path) -ExpectedPersistenceFingerprint ([string]$RecoveryAwarePreparedResult.persistence_fingerprint) -LocalAppDataRoot $LocalAppDataRoot -AppDataRoot $AppDataRoot -Now $Now
    }catch{return & $deny ('recovery-aware-atomic-mutation-threw:'+[string]$_.Exception.Message) $true}
    if($null -eq $mutation -or -not [bool]$mutation.ok){
        $ra=$false;$ro=$false;$rr=$null;$txn=$null;$started=$false
        if($null -ne $mutation){if($mutation.PSObject.Properties['rollback_attempted']){$ra=[bool]$mutation.rollback_attempted};if($mutation.PSObject.Properties['rollback_ok']){$ro=[bool]$mutation.rollback_ok};if($mutation.PSObject.Properties['rollback_result']){$rr=$mutation.rollback_result};if($mutation.PSObject.Properties['transaction_root']){$txn=[string]$mutation.transaction_root};if($mutation.PSObject.Properties['mutation_started']){$started=[bool]$mutation.mutation_started}}
        if($started -and -not $ra){$rr=Restore-CustomAppProductionRecoveryAwarePermitAtomicAfterWrapperFailureV010 -LivePath $livePath -PreparedResult $RecoveryAwarePreparedResult -TransactionRoot $txn -LocalAppDataRoot $LocalAppDataRoot -AppDataRoot $AppDataRoot;$ra=$true;$ro=[bool]$rr.ok}
        else{$cleanup=Remove-CustomAppProductionRecoveryAwarePermitAtomicTransactionV010 -TransactionRoot $txn -LivePath $livePath;if($ra -and $ro -and -not [bool]$cleanup.ok){$ro=$false;$rr=[pscustomobject]@{ok=$false;reason=('primitive-rollback-verified-but-transaction-cleanup-failed:'+[string]$cleanup.reason);primitive_rollback=$rr;cleanup=$cleanup}}}
        return & $deny ('recovery-aware-atomic-mutation-denied:'+[string]$mutation.reason) $true $ra $ro $rr
    }
    $mutationCheck=Test-CustomAppProductionAtomicLiveSwapMutationResultV010 -Result $mutation.result
